import { Pressable, StyleSheet, Text, View } from 'react-native';

type Props = {
  onNavigateHealth: () => void;
  onNavigateTranscribe: () => void;
};

export default function HomeScreen({ onNavigateHealth, onNavigateTranscribe }: Props) {
  return (
    <View style={styles.container}>
      <Text style={styles.title}>Native Bench</Text>
      <Text style={styles.subtitle}>Token economics benchmark</Text>
      <View style={styles.buttons}>
        <Pressable style={styles.button} onPress={onNavigateHealth}>
          <Text style={styles.buttonText}>Health</Text>
        </Pressable>
        <Pressable style={styles.button} onPress={onNavigateTranscribe}>
          <Text style={styles.buttonText}>Transcribe</Text>
        </Pressable>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 24,
  },
  title: {
    fontSize: 32,
    fontWeight: '700',
  },
  subtitle: {
    fontSize: 16,
    color: '#666',
    marginTop: 4,
    marginBottom: 40,
  },
  buttons: {
    width: '100%',
    gap: 12,
  },
  button: {
    backgroundColor: '#007AFF',
    paddingVertical: 14,
    borderRadius: 10,
    alignItems: 'center',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
});

